// safeDial is a dial function that blocks connections to internal/reserved IP addresses.
func safeDial(addr string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, &net.OpError{Op: "dial", Net: "tcp", Addr: nil, Err: err}
	}

	// Resolve host to IPs
	ips, err := net.LookupIP(host)
	if err != nil {
		return nil, &net.OpError{Op: "dial", Net: "tcp", Addr: nil, Err: err}
	}

	// Check all resolved IPs against internal ranges
	var allowed []net.IP
	for _, ip := range ips {
		if isPublicIP(ip) {
			allowed = append(allowed, ip)
		}
	}

	if len(allowed) == 0 {
		return nil, &net.OpError{Op: "dial", Net: "tcp", Addr: nil, Err: fmt.Errorf("access to %s is not allowed", host)}
	}

	// Try each allowed IP until one succeeds
	var lastErr error
	for _, ip := range allowed {
		conn, err := net.DialTimeout("tcp", net.JoinHostPort(ip.String(), port), 5*time.Second)
		if err == nil {
			return conn, nil
		}
		lastErr = err
	}
	return nil, &net.OpError{Op: "dial", Net: "tcp", Addr: nil, Err: fmt.Errorf("failed to connect to %s: %w", host, lastErr)}
}

// isPublicIP checks if an IP address is allowed for external connections.
func isPublicIP(ip net.IP) bool {
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() ||
		ip.IsLinkLocalMulticast() || ip.IsUnspecified() || ip.IsMulticast() {
		return false
	}
	return true
}

