// FetchURLPreview handles POST requests with a JSON body containing a "url" field.
// It fetches the page, extracts the title and meta description, and returns them as JSON.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
    // Ensure the request method is POST
    if !ctx.IsPost() {
        ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
        return
    }

    // Parse the JSON body
    var req struct {
        URL string `json:"url"`
    }
    if err := json.Unmarshal(ctx.PostBody(), &req); err != nil {
        ctx.Error("Invalid JSON body", fasthttp.StatusBadRequest)
        return
    }

    if req.URL == "" {
        ctx.Error("Missing 'url' field", fasthttp.StatusBadRequest)
        return
    }

    // Fetch the URL content
    title, description, err := fetchAndParse(req.URL)
    resp := map[string]string{
        "url":         req.URL,
        "title":       title,
        "description": description,
    }
    if err != nil {
        resp["error"] = err.Error()
    }

    ctx.SetContentType("application/json")
    body, _ := json.Marshal(resp)
    ctx.SetStatusCode(fasthttp.StatusOK)
    ctx.Write(body)
}

func fetchAndParse(rawURL string) (title, description string, err error) {
    client := &fasthttp.Client{
        Dial:         fasthttp.DialDualStack,
        ReadTimeout:  3 * time.Second,
        WriteTimeout: 3 * time.Second,
        // Limit response body size to prevent excessive memory usage (optional)
        MaxResponseBodySize: 10 * 1024 * 1024, // 10 MB
    }

    req := fasthttp.AcquireRequest()
    resp := fasthttp.AcquireResponse()
    defer fasthttp.ReleaseRequest(req)
    defer fasthttp.ReleaseResponse(resp)

    req.SetRequestURI(rawURL)
    req.Header.SetMethod("GET")

    // Follow redirects automatically
    if err := client.DoRedirects(req, resp, 10); err != nil {
        return "", "", fmt.Errorf("failed to fetch URL: %w", err)
    }

    // Check for non-2xx status codes
    if statusCode := resp.StatusCode(); statusCode < 200 || statusCode >= 300 {
        return "", "", fmt.Errorf("unexpected status code: %d", statusCode)
    }

    // Parse HTML
    body := resp.Body()
    title, description = extractMeta(body)
    return title, description, nil
}

func extractMeta(htmlBody []byte) (title, description string) {
    tokenizer := html.NewTokenizer(bytes.NewReader(htmlBody))
    inTitle := false

    for {
        tokenType := tokenizer.Next()
        switch tokenType {
        case html.ErrorToken:
            return title, description
        case html.StartTagToken:
            tn, _ := tokenizer.TagName()
            tag := string(tn)

            if tag == "title" {
                inTitle = true
            } else if tag == "meta" {
                // Look for description or og:description
                var name, property, content string
                for {
                    key, val, more := tokenizer.TagAttr()
                    attr := string(key)
                    switch attr {
                    case "name":
                        name = string(val)
                    case "property":
                        property = string(val)
                    case "content":
                        content = string(val)
                    }
                    if !more {
                        break
                    }
                }
                if strings.EqualFold(name, "description") || strings.EqualFold(property, "og:description") {
                    description = content
                }
            }
        case html.TextToken:
            if inTitle {
                title = string(tokenizer.Text())
                inTitle = false
            }
        }
    }
}

