    defer fasthttp.ReleaseResponse(fetchResp)

    // Fetch the URL using DoRedirects (max 10 redirects).
    if err := client.DoRedirects(fetchReq, fetchResp, 10); err != nil {
        respondError(ctx, fasthttp.StatusInternalServerError, "Failed to fetch URL: "+err.Error())
        return
    }

    // Only accept 2xx status codes.
    if fetchResp.StatusCode() < 200 || fetchResp.StatusCode() >= 300 {
        respondError(ctx, fasthttp.StatusInternalServerError, "Fetch returned non-OK status")
        return
    }

    html := string(fetchResp.Body())
    title := extractTitle(html)
    description := extractDescription(html)

    resp := FetchResponse{
        Title:       title,
        Description: description,
    }

    ctx.SetStatusCode(fasthttp.StatusOK)
    ctx.SetContentType("application/json")
    json.NewEncoder(ctx).Encode(resp)
}

// extractTitle uses a regex to find the <title> tag.
func extractTitle(html string) string {
    matches := titleRegex.FindStringSubmatch(html)
    if len(matches) > 1 {
        return strings.TrimSpace(matches[1])
    }
    return ""
}

// extractDescription uses regex to find a <meta name="description"> tag.
func extractDescription(html string) string {
    matches := metaRegex.FindStringSubmatch(html)
    if len(matches) > 1 {
        return strings.TrimSpace(matches[1])
    }
    matches = metaRegex2.FindStringSubmatch(html)
    if len(matches) > 1 {
        return strings.TrimSpace(matches[1])
    }
    return ""
}

// respondError writes a JSON error response.
func respondError(ctx *fasthttp.RequestCtx, statusCode int, msg string) {
    ctx.SetStatusCode(statusCode)
    ctx.SetContentType("application/json")
    json.NewEncoder(ctx).Encode(FetchResponse{Error: msg})
}

// main starts the HTTP server on port 8080.
func main() {
    requestHandler := func(ctx *fasthttp.RequestCtx) {
        if string(ctx.Path()) == "/fetch-preview" && ctx.IsPost() {
            FetchURLPreview(ctx)
        } else {
            ctx.Error("Not Found", fasthttp.StatusNotFound)
        }
    }

    if err := fasthttp.ListenAndServe(":8080", requestHandler); err != nil {
        panic(err)
    }
}

