// PreviewResponse represents the JSON response structure.
type PreviewResponse struct {
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
	Error       string `json:"error,omitempty"`
}

// FetchURLPreview handles POST requests to fetch URL preview.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
		return
	}

	var req struct {
		URL string `json:"url"`
	}
	body := ctx.PostBody()
	if err := json.Unmarshal(body, &req); err != nil {
		ctx.Error("Invalid JSON", fasthttp.StatusBadRequest)
		return
	}

	targetURL := strings.TrimSpace(req.URL)
	if targetURL == "" {
		ctx.Error("URL is required", fasthttp.StatusBadRequest)
		return
	}

	parsedURL, err := url.ParseRequestURI(targetURL)
	if err != nil {
		ctx.Error("Invalid URL format", fasthttp.StatusBadRequest)
		return
	}
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		ctx.Error("URL must use http or https scheme", fasthttp.StatusBadRequest)
		return
	}

	// Validate the host (no private/reserved IPs) before making any request
	if err := validateHostPublic(parsedURL.Hostname()); err != nil {
		ctx.Error("URL is not allowed: internal host", fasthttp.StatusBadRequest)
		log.Printf("FetchURLPreview: forbidden host %s: %v", parsedURL.Hostname(), err)
		return
	}

	// Client with custom dialer that also rejects private IPs at connection time (defense in depth)
	client := &fasthttp.Client{
		Dial:                safeDial,
		ReadTimeout:         10 * time.Second,
		WriteTimeout:        10 * time.Second,
		MaxIdleConnDuration: 10 * time.Second,
		MaxConnsPerHost:     10,
		MaxResponseBodySize: 10 * 1024 * 1024, // 10MB limit
	}

	freq := fasthttp.AcquireRequest()
	res := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(freq)
	defer fasthttp.ReleaseResponse(res)

	freq.SetRequestURI(targetURL)
	freq.Header.SetMethod("GET")
	freq.Header.Set("User-Agent", "URLPreviewBot/1.0")

	const maxRedirect = 10
	const totalTimeout = 15 * time.Second

	var finalStatus int
	var finalBody []byte

	start := time.Now()
	for i := 0; i <= maxRedirect; i++ {
		if time.Since(start) > totalTimeout {
			ctx.Error("Request timeout", fasthttp.StatusGatewayTimeout)
			return
		}

		err := client.Do(freq, res)
		if err != nil {
			log.Printf("FetchURLPreview: fetch error: %v", err)
			ctx.Error("Failed to fetch URL", fasthttp.StatusBadGateway)
			return
		}

		statusCode := res.StatusCode()
		if statusCode == fasthttp.StatusMovedPermanently ||
			statusCode == fasthttp.StatusFound ||
			statusCode == fasthttp.StatusSeeOther ||
			statusCode == fasthttp.StatusTemporaryRedirect ||
			statusCode == fasthttp.StatusPermanentRedirect {

			if i == maxRedirect {
				ctx.Error("Too many redirects", fasthttp.StatusBadGateway)
				return
			}

			loc := res.Header.Peek("Location")
			if len(loc) == 0 {
				ctx.Error("Redirect without Location header", fasthttp.StatusBadGateway)
				return
			}

			newURL, err := parseRedirectURL(string(loc), parsedURL)
			if err != nil {
				log.Printf("FetchURLPreview: invalid redirect location: %v", err)
				ctx.Error("Invalid redirect location", fasthttp.StatusBadGateway)
				return
			}

			// Validate the new URL before following
			parsedNew, err := url.ParseRequestURI(newURL)
			if err != nil {
				ctx.Error("Invalid redirect URL format", fasthttp.StatusBadGateway)
				return
			}
			if parsedNew.Scheme != "http" && parsedNew.Scheme != "https" {
				ctx.Error("Redirect URL must use http or https", fasthttp.StatusBadGateway)
				return
			}
			if err := validateHostPublic(parsedNew.Hostname()); err != nil {
				ctx.Error("Redirect to internal host not allowed", fasthttp.StatusBadGateway)
				log.Printf("FetchURLPreview: redirect to forbidden host %s: %v", parsedNew.Hostname(), err)
				return
			}

			// Update request for next attempt
			freq.Reset()
			freq.SetRequestURI(newURL)
			freq.Header.SetMethod("GET") // always GET after redirect
			freq.Header.Set("User-Agent", "URLPreviewBot/1.0")
			parsedURL = parsedNew
			res.Reset()
			continue
		}

		// Not a redirect – finished
		finalStatus = statusCode
		finalBody = make([]byte, len(res.Body()))
		copy(finalBody, res.Body())
		break
	}

	if finalStatus != fasthttp.StatusOK {
		if finalStatus == 0 {
			ctx.Error("Unexpected empty response", fasthttp.StatusBadGateway)
			return
		}
		ctx.Error(fmt.Sprintf("Unexpected status code: %d", finalStatus), fasthttp.StatusBadGateway)
		return
	}

	if len(finalBody) == 0 {
		ctx.Error("Empty response body", fasthttp.StatusBadGateway)
		return
	}

	// Optional: only parse if content is HTML (check Content-Type)
	contentType := string(res.Header.ContentType())
	if !strings.HasPrefix(contentType, "text/html") && !strings.HasPrefix(contentType, "application/xhtml+xml") {
		ctx.Error("Unsupported content type", fasthttp.StatusUnsupportedMediaType)
		return
	}

