	if err != nil {
		log.Printf("FetchURLPreview: HTML parse error: %v", err)
		ctx.Error("Failed to parse HTML", fasthttp.StatusInternalServerError)
		return
	}

	resp := PreviewResponse{
		Title:       title,
		Description: description,
	}

	ctx.SetContentType("application/json; charset=utf-8")
	if err := json.NewEncoder(ctx).Encode(resp); err != nil {
		log.Printf("FetchURLPreview: JSON encode error: %v", err)
		ctx.Error("Internal error", fasthttp.StatusInternalServerError)
	}
}

// validateHostPublic ensures that the resolved host (or the IP itself) does not point to a private or reserved address.
func validateHostPublic(host string) error {
	// If it's an IP address, net.LookupIP will resolve it to itself.
	ips, err := net.LookupIP(host)
	if err != nil {
		return fmt.Errorf("could not resolve host: %w", err)
	}
	for _, ip := range ips {
		if !isPublicIP(ip) {
			return fmt.Errorf("private or restricted IP %s", ip.String())
		}
	}
	return nil
}

// isPublicIP returns false for private, loopback, multicast, link-local,
// unspecified, and some special IP ranges (e.g. AWS metadata 169.254.169.254).
func isPublicIP(ip net.IP) bool {
	if ip.IsLoopback() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsMulticast() || ip.IsUnspecified() {
		return false
	}
	if ip4 := ip.To4(); ip4 != nil {
		// Check private ranges manually (IsPrivate does not work for all Go versions consistently)
		switch {
		case ip4[0] == 10:
			return false
		case ip4[0] == 172 && ip4[1] >= 16 && ip4[1] <= 31:
			return false
		case ip4[0] == 192 && ip4[1] == 168:
			return false
		case ip4[0] == 169 && ip4[1] == 254:
			// 169.254.0.0/16 (link-local) is already caught, but explicitly block metadata service 169.254.169.254
			return false
		}
		return true
	}
	// IPv6
	return !(ip[0]&0xfe == 0xfc || // fc00::/7 unique local
		(ip[0] == 0xfe && ip[1]&0xc0 == 0x80)) // fe80::/10 link-local
}

// safeDial is a custom dial function that verifies the resolved address is public before connecting.
// It conforms to fasthttp.DialFunc: func(addr string) (net.Conn, error)
func safeDial(addr string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, err
	}
	if err := validateHostPublic(host); err != nil {
		return nil, fmt.Errorf("dial rejected: %w", err)
	}
	// Use the standard dialer with dual stack support
	d := &net.Dialer{
		Timeout:   10 * time.Second,
		KeepAlive: 10 * time.Second,
	}
	return d.Dial("tcp", net.JoinHostPort(host, port))
}

// parseRedirectURL combines the base URL and the relative location header.
func parseRedirectURL(location string, base *url.URL) (string, error) {
	locURL, err := url.Parse(location)
	if err != nil {
		return "", err
	}
	return base.ResolveReference(locURL).String(), nil
}

// parseHTMLPreview extracts title and meta description from HTML reader.
func parseHTMLPreview(r io.Reader) (title, description string, err error) {
	doc, err := html.Parse(r)
	if err != nil {
		return "", "", err
	}
	var extract func(*html.Node)
	extract = func(n *html.Node) {
		if n.Type == html.ElementNode {
			if n.Data == "title" && title == "" && n.FirstChild != nil {
				title = n.FirstChild.Data
			}
			if n.Data == "meta" {
				var name, content string
				for _, attr := range n.Attr {
					if attr.Key == "name" {
						name = attr.Val
					}
					if attr.Key == "content" {
						content = attr.Val
					}
				}
				if name == "description" && description == "" {
					description = content
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			extract(c)
		}
	}
	extract(doc)
	return title, description, nil
}

