    if !ctx.IsPost() {
        ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
        ctx.SetContentType("application/json")
        json.NewEncoder(ctx).Encode(URLPreview{Error: "only POST method is allowed"})
        return
    }

