package main

import (
	"bytes"
	"encoding/json"
	"log"
	"net/url"
	"strings"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

func main() {
	server := &fasthttp.Server{
		Handler: func(ctx *fasthttp.RequestCtx) {
			switch string(ctx.Path()) {
			case "/preview":
				FetchURLPreview(ctx)
			default:
				ctx.Error("not found", fasthttp.StatusNotFound)
			}
		},
	}

	log.Fatal(server.ListenAndServe(":8080"))
}

// FetchURLPreview handles POST requests with a JSON body containing a "url" field.
// It fetches the page, extracts title and meta description, and returns them as JSON.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Parse request body
	var body struct {
		URL string `json:"url"`
	}
	if err := json.Unmarshal(ctx.PostBody(), &body); err != nil || body.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.WriteString(`{"error":"invalid request body"}`)
		return
	}

	// Validate URL
	u, err := url.Parse(body.URL)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.WriteString(`{"error":"invalid url"}`)
		return
	}

	// Prepare fasthttp request/response objects
	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(body.URL)
	req.Header.SetMethod("GET")

	// Create client with Dial set to DialDualStack and use DoRedirects
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}
	if err := client.DoRedirects(req, resp, 10); err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		ctx.WriteString(`{"error":"failed to fetch url"}`)
		return
	}

	// Parse the HTML
	doc, err := html.Parse(bytes.NewReader(resp.Body()))
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		ctx.WriteString(`{"error":"failed to parse html"}`)
		return
	}

	title := extractTitle(doc)
	description := extractDescription(doc)

	// Build response
	result := map[string]string{
		"title":       title,
		"description": description,
	}
	respJSON, _ := json.Marshal(result)

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	ctx.Write(respJSON)
}

// extractTitle traverses the HTML node tree looking for the <title> element
// and returns its text content.
func extractTitle(n *html.Node) string {
	if n.Type == html.ElementNode && n.Data == "title" {
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			if c.Type == html.TextNode {
				return strings.TrimSpace(c.Data)
			}
		}
	}
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		if title := extractTitle(c); title != "" {
			return title
		}
	}
	return ""
}

// extractDescription traverses the HTML node tree looking for a <meta name="description">
// element and returns its content attribute value.
func extractDescription(n *html.Node) string {
	if n.Type == html.ElementNode && n.Data == "meta" {
		var name, content string
		for _, a := range n.Attr {
			if a.Key == "name" {
				name = a.Val
			} else if a.Key == "content" {
				content = a.Val
			}
		}
		if strings.EqualFold(name, "description") {
			return content
		}
	}
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		if desc := extractDescription(c); desc != "" {
			return desc
		}
	}
	return ""
}

