package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/url"
	"strings"
	"time"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

// PreviewResponse represents the JSON response structure.
type PreviewResponse struct {
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
	Error       string `json:"error,omitempty"`
}

// FetchURLPreview handles POST requests to fetch URL preview.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		sendJSONError(ctx, fasthttp.StatusMethodNotAllowed, "Method not allowed")
		return
	}

	var req struct {
		URL string `json:"url"`
	}
	if err := json.Unmarshal(ctx.PostBody(), &req); err != nil {
		sendJSONError(ctx, fasthttp.StatusBadRequest, "Invalid JSON")
		return
	}

	targetURL := strings.TrimSpace(req.URL)
	if targetURL == "" {
		sendJSONError(ctx, fasthttp.StatusBadRequest, "URL is required")
		return
	}

	parsedURL, err := url.Parse(targetURL)
	if err != nil {
		sendJSONError(ctx, fasthttp.StatusBadRequest, "Invalid URL format")
		return
	}
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		sendJSONError(ctx, fasthttp.StatusBadRequest, "URL must use http or https scheme")
		return
	}

	client := &fasthttp.Client{
		Dial:                fasthttp.DialDualStack,
		ReadTimeout:         10 * time.Second,
		WriteTimeout:        10 * time.Second,
		MaxIdleConnDuration: 10 * time.Second,
		MaxConnsPerHost:     10,
	}

	freq := fasthttp.AcquireRequest()
	res := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(freq)
	defer fasthttp.ReleaseResponse(res)

	freq.SetRequestURI(targetURL)
	freq.Header.SetMethod("GET")
	freq.Header.Set("User-Agent", "URLPreviewBot/1.0")

	if err := client.DoRedirects(freq, res, 10); err != nil {
		sendJSONError(ctx, fasthttp.StatusBadGateway, fmt.Sprintf("Failed to fetch URL: %v", err))
		return
	}

	if res.StatusCode() != fasthttp.StatusOK {
		sendJSONError(ctx, fasthttp.StatusBadGateway, fmt.Sprintf("Unexpected status code: %d", res.StatusCode()))
		return
	}

	bodyBytes := res.Body()
	if len(bodyBytes) == 0 {
		sendJSONError(ctx, fasthttp.StatusBadGateway, "Empty response body")
		return
	}

	title, description, err := parseHTMLPreview(bytes.NewReader(bodyBytes))
	if err != nil {
		sendJSONError(ctx, fasthttp.StatusInternalServerError, fmt.Sprintf("Failed to parse HTML: %v", err))
		return
	}

	resp := PreviewResponse{
		Title:       title,
		Description: description,
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json; charset=utf-8")
	if err := json.NewEncoder(ctx).Encode(resp); err != nil {
		sendJSONError(ctx, fasthttp.StatusInternalServerError, "Failed to encode response")
	}
}

// sendJSONError writes a JSON error response with the given status code and message.
func sendJSONError(ctx *fasthttp.RequestCtx, statusCode int, msg string) {
	ctx.SetStatusCode(statusCode)
	ctx.SetContentType("application/json; charset=utf-8")
	resp := PreviewResponse{Error: msg}
	json.NewEncoder(ctx).Encode(resp)
}

// parseHTMLPreview extracts the title and meta description from HTML content.
func parseHTMLPreview(r io.Reader) (string, string, error) {
	doc, err := html.Parse(r)
	if err != nil {
		return "", "", fmt.Errorf("html parse: %w", err)
	}

	var title, description string
	var walk func(*html.Node)
	walk = func(n *html.Node) {
		if n.Type == html.ElementNode {
			switch n.Data {
			case "title":
				title = extractText(n)
			case "meta":
				var name, content string
				for _, attr := range n.Attr {
					if attr.Key == "name" {
						name = attr.Val
					} else if attr.Key == "content" {
						content = attr.Val
					}
				}
				if name == "description" && description == "" {
					description = content
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			walk(c)
		}
	}
	walk(doc)
	return title, description, nil
}

// extractText returns all text content within a node (including nested elements).
func extractText(n *html.Node) string {
	if n.Type == html.TextNode {
		return n.Data
	}
	var sb strings.Builder
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		sb.WriteString(extractText(c))
	}
	return sb.String()
}

