// FetchURLPreview handles POST request with a JSON body containing "url" field.
// It fetches the URL, extracts page title and meta description, and returns JSON.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
    // Only accept POST
    if !ctx.IsPost() {
        ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
        return
    }

    // Parse JSON body
    body := ctx.PostBody()
    var req URLRequest
    if err := json.Unmarshal(body, &req); err != nil {
        ctx.SetStatusCode(fasthttp.StatusBadRequest)
        ctx.SetContentType("application/json")
        json.NewEncoder(ctx).Encode(map[string]string{"error": "Invalid JSON"})
        return
    }

    // Validate URL
    if req.URL == "" {
        ctx.SetStatusCode(fasthttp.StatusBadRequest)
        ctx.SetContentType("application/json")
        json.NewEncoder(ctx).Encode(map[string]string{"error": "URL is required"})
        return
    }

    if !strings.HasPrefix(req.URL, "http://") && !strings.HasPrefix(req.URL, "https://") {
        ctx.SetStatusCode(fasthttp.StatusBadRequest)
        ctx.SetContentType("application/json")
        json.NewEncoder(ctx).Encode(map[string]string{"error": "URL must start with http:// or https://"})
        return
    }

    // Fetch the URL
    request := fasthttp.AcquireRequest()
    response := fasthttp.AcquireResponse()
    defer fasthttp.ReleaseRequest(request)
    defer fasthttp.ReleaseResponse(response)

    request.SetRequestURI(req.URL)

    // Use DoRedirects to follow redirects (max 10)
    err := previewClient.DoRedirects(request, response, 10)
    if err != nil {
        ctx.SetStatusCode(fasthttp.StatusBadGateway)
        ctx.SetContentType("application/json")
        json.NewEncoder(ctx).Encode(map[string]string{
            "error": fmt.Sprintf("Failed to fetch URL: %v", err),
        })
        return
    }

    // Extract title and description from HTML body
    htmlBody := response.Body()
    title := extractTitle(htmlBody)
    description := extractMetaDescription(htmlBody)

    // Build JSON response
    result := PreviewResponse{
        Title:       title,
        Description: description,
    }

    ctx.SetStatusCode(fasthttp.StatusOK)
    ctx.SetContentType("application/json")
    json.NewEncoder(ctx).Encode(result)
}

// extractTitle finds the <title> tag content in the HTML.
func extractTitle(html []byte) string {
    lower := strings.ToLower(string(html))
    startTag := "<title"
    titleStart := strings.Index(lower, startTag)
    if titleStart == -1 {
        return ""
    }
    // Find end of the opening tag
    endOpening := strings.Index(lower[titleStart:], ">")
    if endOpening == -1 {
        return ""
    }
    contentStart := titleStart + endOpening + 1
    titleEnd := strings.Index(lower[contentStart:], "</title>")
    if titleEnd == -1 {
        return ""
    }
    content := string(html[contentStart : contentStart+titleEnd])
    return strings.TrimSpace(content)
}

// extractMetaDescription looks for <meta name="description" content="..."> and returns the content.
func extractMetaDescription(html []byte) string {
    lower := strings.ToLower(string(html))
    pos := 0
    for {
        // Find next <meta tag
        start := strings.Index(lower[pos:], "<meta")
        if start == -1 {
            break
        }
        start += pos
        // Find the end of this tag
        end := strings.Index(lower[start:], ">")
        if end == -1 {
            break
        }
        tag := string(html[start : start+end+1])
        tagLower := strings.ToLower(tag)

        // Check if it's a description meta tag
        if strings.Contains(tagLower, "name=\"description\"") ||
            strings.Contains(tagLower, "name='description'") {
            // Extract content attribute
            // Look for content=" or content='
            for _, attr := range []string{"content=\"", "content='"} {
                contentIdx := strings.Index(tag, attr)
                if contentIdx != -1 {
                    valueStart := contentIdx + len(attr)
                    // Find the closing quote
                    var valueEnd int
                    if attr[len(attr)-1] == '"' {
                        valueEnd = strings.Index(tag[valueStart:], "\"")
                    } else {
                        valueEnd = strings.Index(tag[valueStart:], "'")
                    }
                    if valueEnd != -1 {
                        return strings.TrimSpace(tag[valueStart : valueStart+valueEnd])
                    }
                }
            }
        }

        // Move past this tag to continue searching
        pos = start + end + 1
    }
    return ""
}

