package main

import (
	"encoding/json"
	"fmt"
	"log"
	"regexp"
	"strings"

	"github.com/valyala/fasthttp"
)

// URLPreviewResponse represents the extracted preview data.
type URLPreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

// ErrorResponse represents a generic error message.
type ErrorResponse struct {
	Error string `json:"error"`
}

var (
	titleRegex       = regexp.MustCompile(`(?i)<title[^>]*>([^<]+)</title>`)
	metaDescRegex    = regexp.MustCompile(`(?i)<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["']`)
)

// FetchURLPreview handles POST requests with a JSON body containing a "url" field.
// It fetches the URL, extracts title and meta description, and returns them as JSON.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Ensure request method is POST
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		return
	}

	// Parse JSON body
	var requestBody struct {
		URL string `json:"url"`
	}
	if err := json.Unmarshal(ctx.PostBody(), &requestBody); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		json.NewEncoder(ctx).Encode(ErrorResponse{Error: "invalid JSON"})
		return
	}

	if strings.TrimSpace(requestBody.URL) == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		json.NewEncoder(ctx).Encode(ErrorResponse{Error: "url is required"})
		return
	}

	// Prepare HTTP client with DualStack dialer
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(requestBody.URL)

	// Fetch URL following up to 10 redirects
	if err := client.DoRedirects(req, resp, 10); err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		json.NewEncoder(ctx).Encode(ErrorResponse{Error: fmt.Sprintf("failed to fetch URL: %v", err)})
		return
	}

	body := resp.Body()
	htmlContent := string(body)

	title := extractTitle(htmlContent)
	description := extractMetaDescription(htmlContent)

	ctx.SetContentType("application/json")
	ctx.SetStatusCode(fasthttp.StatusOK)
	json.NewEncoder(ctx).Encode(URLPreviewResponse{
		Title:       title,
		Description: description,
	})
}

// extractTitle parses the HTML and returns the content of the <title> tag.
func extractTitle(html string) string {
	matches := titleRegex.FindStringSubmatch(html)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1])
	}
	return ""
}

// extractMetaDescription parses the HTML and returns the content attribute of
// the meta description tag.
func extractMetaDescription(html string) string {
	matches := metaDescRegex.FindStringSubmatch(html)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1])
	}
	return ""
}

func main() {
	log.Println("Starting server on :8080")
	if err := fasthttp.ListenAndServe(":8080", FetchURLPreview); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}

