        Description: description,
    }

    responseBody, err := json.Marshal(response)
    if err != nil {
        ctx.Error("Internal server error", fasthttp.StatusInternalServerError)
        return
    }

    ctx.SetContentType("application/json")
    ctx.Write(responseBody)
}

// extractMeta extracts the title and meta description from an HTML string.
func extractMeta(htmlContent string) (string, string) {
    title := ""
    description := ""

    // Extract <title>...</title>
    titleRegex := regexp.MustCompile(`(?i)<title[^>]*>(.*?)</title>`)
    if matches := titleRegex.FindStringSubmatch(htmlContent); len(matches) > 1 {
        title = strings.TrimSpace(matches[1])
    }

    // Extract <meta name="description" content="...">
    // Handles both orderings of name and content attributes.
    descRegex := regexp.MustCompile(`(?i)<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']`)
    if matches := descRegex.FindStringSubmatch(htmlContent); len(matches) > 1 {
        description = strings.TrimSpace(matches[1])
    } else {
        // Alternate ordering: content first, name second
        descRegex2 := regexp.MustCompile(`(?i)<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description["']`)
        if matches := descRegex2.FindStringSubmatch(htmlContent); len(matches) > 1 {
            description = strings.TrimSpace(matches[1])
        }
    }

    return title, description
}

