func FetchURLPreview(ctx *fasthttp.RequestCtx) {
    // Allow only POST requests
    if !ctx.IsPost() {
        ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
        ctx.Write([]byte(`{"error":"Method not allowed"}`))
        return
    }

    body := ctx.PostBody()
    var req fetchRequest
    if err := json.Unmarshal(body, &req); err != nil {
        ctx.SetStatusCode(fasthttp.StatusBadRequest)
        ctx.Write([]byte(`{"error":"Invalid JSON"}`))
        return
    }

    if req.URL == "" {
        ctx.SetStatusCode(fasthttp.StatusBadRequest)
        ctx.Write([]byte(`{"error":"URL is required"}`))
        return
    }

    // Validate the URL format
    if _, err := url.ParseRequestURI(req.URL); err != nil {
        ctx.SetStatusCode(fasthttp.StatusBadRequest)
        ctx.Write([]byte(`{"error":"Invalid URL"}`))
        return
    }

    // Create a fasthttp client with DualStack enabled
    client := &fasthttp.Client{
        Dial: fasthttp.DialDualStack,
    }

    // Acquire request/response objects from pool for efficiency
    fasthttpReq := fasthttp.AcquireRequest()
    fasthttpResp := fasthttp.AcquireResponse()
    defer fasthttp.ReleaseRequest(fasthttpReq)
    defer fasthttp.ReleaseResponse(fasthttpResp)

    fasthttpReq.SetRequestURI(req.URL)

    // Fetch the URL, following up to 10 redirects
    err := client.DoRedirects(fasthttpReq, fasthttpResp, 10)
    if err != nil {
        ctx.SetStatusCode(fasthttp.StatusInternalServerError)
        ctx.Write([]byte(`{"error":"Failed to fetch URL"}`))
        return
    }

    // Extract title and description from the HTML response body
    htmlBody := fasthttpResp.Body()
    title, description := extractMeta(htmlBody)

    resp := fetchResponse{
        Title:       title,
        Description: description,
    }

    jsonResp, err := json.Marshal(resp)
    if err != nil {
        ctx.SetStatusCode(fasthttp.StatusInternalServerError)
        ctx.Write([]byte(`{"error":"Failed to marshal response"}`))
        return
    }

    ctx.SetContentType("application/json")
    ctx.Write(jsonResp)
}

// extractMeta parses HTML and returns the first <title> text and the content
// attribute of the first <meta name="description"> tag.
func extractMeta(htmlContent []byte) (title, description string) {
    r := strings.NewReader(string(htmlContent))
    z := html.NewTokenizer(r)

    inTitle := false
    for {
        tt := z.Next()
        switch tt {
        case html.ErrorToken:
            return
        case html.StartTagToken, html.SelfClosingTagToken:
            tn, _ := z.TagName()
            tag := string(tn)

            if tag == "title" {
                inTitle = true
            } else if tag == "meta" {
                var name, content string
                for {
                    key, val, more := z.TagAttr()
                    ks := string(key)
                    vs := string(val)
                    if ks == "name" {
                        name = vs
                    } else if ks == "content" {
                        content = vs
                    }
                    if !more {
                        break
                    }
                }
                if strings.ToLower(name) == "description" {
                    description = content
                }
            }

        case html.TextToken:
            if inTitle {
                title = string(z.Text())
                inTitle = false
            }
        }
    }
