				return
			}
			newURLStr := newURL.String()
			if newURL.Scheme != "http" && newURL.Scheme != "https" {
				ctx.Error("Redirect URL must use http or https scheme", fasthttp.StatusBadGateway)
				return
			}
			if err := validateHost(newURL.Hostname()); err != nil {
				ctx.Error("Redirect points to an internal or forbidden host", fasthttp.StatusBadGateway)
				return
			}
			currentURL = newURLStr
			remainingRedirects--
			continue
		}

		ctx.Error("Failed to fetch URL", fasthttp.StatusBadGateway)
		return
	}

	bodyBytes := res.Body()
	if len(bodyBytes) == 0 {
		ctx.Error("Empty response body", fasthttp.StatusBadGateway)
		return
	}
	if len(bodyBytes) > maxResponseBodySize {
		ctx.Error("Response body too large", fasthttp.StatusBadGateway)
		return
	}

	title, description, err := parseHTMLPreview(bytes.NewReader(bodyBytes))
	if err != nil {
		ctx.Error("Failed to parse HTML", fasthttp.StatusInternalServerError)
		return
	}

	resp := PreviewResponse{
		Title:       title,
		Description: description,
	}

	ctx.SetContentType("application/json; charset=utf-8")
	if err := json.NewEncoder(ctx).Encode(resp); err != nil {
		ctx.Error("Failed to encode response", fasthttp.StatusInternalServerError)
		return
	}
}

// validateHost resolves host to IP addresses and rejects private, loopback, and other internal/unsafe IPs.
func validateHost(host string) error {
	// If host is already an IP address, check it directly.
	if ip := net.ParseIP(host); ip != nil {
		if !isSafeIP(ip) {
			return fmt.Errorf("unsafe IP: %s", host)
		}
		return nil
	}
	// Resolve hostname.
	ips, err := net.LookupIP(host)
	if err != nil {
		return fmt.Errorf("could not resolve host: %w", err)
	}
	if len(ips) == 0 {
		return fmt.Errorf("no IPs resolved for host")
	}
	for _, ip := range ips {
		if !isSafeIP(ip) {
			return fmt.Errorf("host resolves to unsafe IP: %s", ip.String())
		}
	}
	return nil
}

// isSafeIP checks whether the given IP is allowed (not private, loopback, link-local, etc.).
func isSafeIP(ip net.IP) bool {
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsUnspecified() {
		return false
	}
	return true
}

// parseHTMLPreview extracts title and meta description from HTML.
func parseHTMLPreview(r io.Reader) (title, description string, err error) {
	z := html.NewTokenizer(r)
	inTitle := false
	var titleBuilder strings.Builder

	for {
		tt := z.Next()
		switch tt {
		case html.ErrorToken:
			if z.Err() == io.EOF {
				return titleBuilder.String(), description, nil
			}
			return "", "", z.Err()
		case html.StartTagToken, html.SelfClosingTagToken:
			tagName, _ := z.TagName()
			if string(tagName) == "title" {
				inTitle = true
				titleBuilder.Reset()
				continue
			}
			if string(tagName) == "meta" && description == "" {
				// Read attributes.
				var name, content string
				for {
					attrName, attrVal, more := z.TagAttr()
					key := string(attrName)
					val := string(attrVal)
					if strings.EqualFold(key, "name") {
						name = val
					} else if strings.EqualFold(key, "content") {
						content = val
					}
					if !more {
						break
					}
				}
				if strings.EqualFold(name, "description") && content != "" {
					description = content
				}
			}
		case html.EndTagToken:
			tagName, _ := z.TagName()
			if string(tagName) == "title" && inTitle {
				inTitle = false
			}
		case html.TextToken:
			if inTitle {
				titleBuilder.Write(z.Text())
			}
		}
	}
}

