// FetchURLPreview handles POST requests to fetch a URL preview.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
		return
	}

	body := ctx.PostBody()
	var req struct {
		URL string `json:"url"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		ctx.Error("Bad Request", fasthttp.StatusBadRequest)
		return
	}
	if req.URL == "" {
		ctx.Error("Missing url field", fasthttp.StatusBadRequest)
		return
	}

	parsedURL, err := url.Parse(req.URL)
	if err != nil || (parsedURL.Scheme != "http" && parsedURL.Scheme != "https") {
		ctx.Error("Invalid URL", fasthttp.StatusBadRequest)
		return
	}

	// Prepare the request with a 3-second timeout.
	fReq := fasthttp.AcquireRequest()
	fResp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(fReq)
	defer fasthttp.ReleaseResponse(fResp)

	fReq.SetRequestURI(req.URL)
	fReq.SetTimeout(3 * time.Second)

	// Use a client that dials dual stack networks.
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	err = client.DoRedirects(fReq, fResp, 10)
	if err != nil {
		ctx.Error(fmt.Sprintf("Failed to fetch URL: %v", err), fasthttp.StatusBadGateway)
		return
	}
	if fResp.StatusCode() != fasthttp.StatusOK {
		ctx.Error(fmt.Sprintf("Server returned %d", fResp.StatusCode()), fasthttp.StatusBadGateway)
		return
	}

	body = fResp.Body()
	title, description := parseHTML(body)

	result := map[string]string{
		"title":       title,
		"description": description,
	}

	ctx.SetContentType("application/json")
	jsonBytes, err := json.Marshal(result)
	if err != nil {
		ctx.Error("Internal server error", fasthttp.StatusInternalServerError)
		return
	}
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(jsonBytes)
}

// parseHTML extracts the page title and meta description from the given HTML data.
func parseHTML(data []byte) (string, string) {
	tokenizer := html.NewTokenizer(bytes.NewReader(data))
	var title, description string

	for {
		tt := tokenizer.Next()
		switch tt {
		case html.ErrorToken:
			return title, description
		case html.StartTagToken, html.SelfClosingTagToken:
			tagName, hasAttr := tokenizer.TagName()
			tag := string(tagName)

			// Extract <title> content
			if tag == "title" {
				tt = tokenizer.Next()
				if tt == html.TextToken {
					title = string(tokenizer.Text())
				}
				continue
			}

			// Look for <meta name="description"> content
			if tag == "meta" && hasAttr {
				var name, content string
				for {
					key, val, more := tokenizer.TagAttr()
					if bytes.Equal(key, []byte("name")) {
						name = string(val)
					} else if bytes.Equal(key, []byte("content")) {
						content = string(val)
					}
					if !more {
						break
					}
				}
				if name == "description" {
					description = content
				}
			}
		}
	}
}

