import (
    "encoding/json"
    "strings"

    "github.com/valyala/fasthttp"
    "golang.org/x/net/html"
)

// FetchURLPreview handles POST requests with a JSON body containing a "url" field.
// It fetches the HTML of the URL, extracts the title and meta description, and returns them as JSON.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
    // Only accept POST requests
    if !ctx.IsPost() {
        ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
        return
    }

    // Parse JSON body
    var body struct {
        URL string `json:"url"`
    }
    if err := json.Unmarshal(ctx.PostBody(), &body); err != nil {
        ctx.Error("Invalid JSON body", fasthttp.StatusBadRequest)
        return
    }
    if body.URL == "" {
        ctx.Error("Missing required 'url' field", fasthttp.StatusBadRequest)
        return
    }

    // Create a fasthttp client with dual‑stack dialing
    client := &fasthttp.Client{
        Dial: fasthttp.DialDualStack,
    }

    req := fasthttp.AcquireRequest()
    defer fasthttp.ReleaseRequest(req)

    resp := fasthttp.AcquireResponse()
    defer fasthttp.ReleaseResponse(resp)

    req.SetRequestURI(body.URL)

    // Fetch the URL using DoRedirects (max 10 redirects)
    if err := client.DoRedirects(req, resp, 10); err != nil {
        ctx.Error("Failed to fetch URL: "+err.Error(), fasthttp.StatusBadGateway)
        return
    }

    // Extract title and description from the HTML body
    content := resp.Body()
    title, description := parseHTML(string(content))

    result := map[string]string{
        "title":       title,
        "description": description,
    }

    respJSON, _ := json.Marshal(result)
    ctx.SetContentType("application/json")
    ctx.SetStatusCode(fasthttp.StatusOK)
    ctx.Write(respJSON)
}

// parseHTML extracts the page title and meta description from raw HTML.
func parseHTML(htmlStr string) (string, string) {
    doc, err := html.Parse(strings.NewReader(htmlStr))
    if err != nil {
        return "", ""
    }

    var title, description string
    var traverse func(*html.Node)

    traverse = func(n *html.Node) {
        if n.Type == html.ElementNode {
            switch n.Data {
            case "title":
                title = extractText(n)
            case "meta":
                var name, content string
                for _, attr := range n.Attr {
                    if attr.Key == "name" {
                        name = attr.Val
                    } else if attr.Key == "content" {
                        content = attr.Val
                    }
                }
                if strings.EqualFold(name, "description") {
                    description = content
                }
            }
        }
        for c := n.FirstChild; c != nil; c = c.NextSibling {
            traverse(c)
        }
    }

    traverse(doc)
    return title, description
}

// extractText recursively collects text nodes from an HTML node.
func extractText(n *html.Node) string {
    if n.Type == html.TextNode {
        return n.Data
    }
    var sb strings.Builder
    for c := n.FirstChild; c != nil; c = c.NextSibling {
        sb.WriteString(extractText(c))
    }
    return strings.TrimSpace(sb.String())
}

func main() {
    // Simple router: /fetch-url-preview triggers our handler
    handler := func(ctx *fasthttp.RequestCtx) {
        switch string(ctx.Path()) {
        case "/fetch-url-preview":
            FetchURLPreview(ctx)
        default:
            ctx.Error("Not found", fasthttp.StatusNotFound)
        }
    }

    // Start the server on port 8080
    if err := fasthttp.ListenAndServe(":8080", handler); err != nil {
        panic(err)
    }
}

