// FetchURLPreview handles POST requests to fetch URL preview.
// It implements SSRF protection, body size limitation, and secure redirect handling.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
		return
	}

	var req struct {
		URL string `json:"url"`
	}

	body := ctx.PostBody()
	if err := json.Unmarshal(body, &req); err != nil {
		ctx.Error("Invalid JSON", fasthttp.StatusBadRequest)
		return
	}

	targetURL := strings.TrimSpace(req.URL)
	if targetURL == "" {
		ctx.Error("URL is required", fasthttp.StatusBadRequest)
		return
	}

	// Validate URL format
	parsedURL, err := url.ParseRequestURI(targetURL)
	if err != nil {
		ctx.Error("Invalid URL format", fasthttp.StatusBadRequest)
		return
	}

	// Only allow http and https schemes
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		ctx.Error("URL must use http or https scheme", fasthttp.StatusBadRequest)
		return
	}

	// Pre-validate the host to prevent SSRF (perform a quick DNS check with a timeout)
	validateCtx, cancelValidate := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancelValidate()
	if err := validateHost(validateCtx, parsedURL.Host); err != nil {
		ctx.Error(fmt.Sprintf("URL host not allowed: %v", err), fasthttp.StatusBadRequest)
		return
	}

	// Create an HTTP client with SSRF-protective dialer and redirect validator.
	client := &http.Client{
		Timeout: 15 * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			// Limit total redirects
			if len(via) >= 10 {
				return fmt.Errorf("too many redirects")
			}
			newURL := req.URL
			if newURL.Scheme != "http" && newURL.Scheme != "https" {
				return fmt.Errorf("redirect to non-http scheme: %s", newURL.Scheme)
			}
			// Re-validate host for every redirect using the request context
			if err := validateHost(req.Context(), newURL.Host); err != nil {
				return err
			}
			return nil
		},
		Transport: &http.Transport{
			DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
				host, port, err := net.SplitHostPort(addr)
				if err != nil {
					return nil, err
				}

				// If the host is a literal IP, check immediately
				if ip := net.ParseIP(host); ip != nil {
					if !ip.IsGlobalUnicast() {
						return nil, fmt.Errorf("resolved IP %s is not global unicast", ip)
					}
					// dial directly with the IP
					dialer := &net.Dialer{}
					return dialer.DialContext(ctx, network, net.JoinHostPort(ip.String(), port))
				}

				// Resolve the hostname and filter to only global unicast addresses
				ips, err := net.DefaultResolver.LookupIPAddr(ctx, host)
				if err != nil {
					return nil, err
				}
				var allowed []net.IP
				for _, ip := range ips {
					if ip.IP.IsGlobalUnicast() {
						allowed = append(allowed, ip.IP)
					}
				}
				if len(allowed) == 0 {
					return nil, fmt.Errorf("host %q resolves to no global unicast address", host)
				}

				dialer := &net.Dialer{}
				// Dial the first available global unicast IP
				return dialer.DialContext(ctx, network, net.JoinHostPort(allowed[0].String(), port))
			},
		},
	}

	// Create request with timeout context
	reqCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	httpReq, err := http.NewRequestWithContext(reqCtx, http.MethodGet, targetURL, nil)
	if err != nil {
		ctx.Error(fmt.Sprintf("Failed to create request: %v", err), fasthttp.StatusInternalServerError)
		return
	}
	httpReq.Header.Set("User-Agent", "URLPreviewBot/1.0")

	resp, err := client.Do(httpReq)
	if err != nil {
		ctx.Error(fmt.Sprintf("Failed to fetch URL: %v", err), fasthttp.StatusBadGateway)
		return
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		ctx.Error(fmt.Sprintf("Unexpected status code: %d", resp.StatusCode), fasthttp.StatusBadGateway)
		return
	}

	// Limit response body size to 2 MB to prevent memory exhaustion
	limitedReader := io.LimitReader(resp.Body, 2*1024*1024)
	bodyBytes, err := io.ReadAll(limitedReader)
	if err != nil {
		ctx.Error(fmt.Sprintf("Failed to read response body: %v", err), fasthttp.StatusBadGateway)
		return
	}

	if len(bodyBytes) == 0 {
		ctx.Error("Empty response body", fasthttp.StatusBadGateway)
		return
	}

	title, description, err := parseHTMLPreview(strings.NewReader(string(bodyBytes)))
	if err != nil {
		ctx.Error(fmt.Sprintf("Failed to parse HTML: %v", err), fasthttp.StatusInternalServerError)
		return
	}

	respPayload := PreviewResponse{
		Title:       title,
		Description: description,
	}

	ctx.SetContentType("application/json; charset=utf-8")
	if err := json.NewEncoder(ctx).Encode(respPayload); err != nil {
		ctx.Error("Failed to encode response", fasthttp.StatusInternalServerError)
	}
}

// validateHost checks whether the given host (host or host:port) resolves only to
// globally routable unicast addresses, preventing SSRF to internal/private networks.
// It accepts a context to cancel DNS lookups and avoid indefinite blocking.
func validateHost(ctx context.Context, hostPort string) error {
	host, _, err := net.SplitHostPort(hostPort)
	if err != nil {
		// If no port is present, hostPort is just the host
		host = hostPort
	}

	// Handle literal IP addresses
	if ip := net.ParseIP(host); ip != nil {
		if !ip.IsGlobalUnicast() {
			return fmt.Errorf("literal IP %s is not globally reachable", ip)
		}
		return nil
	}

	// Resolve hostname using the provided context
	ips, err := net.DefaultResolver.LookupIPAddr(ctx, host)
	if err != nil {
		return fmt.Errorf("failed to resolve host %q: %w", host, err)
	}
	if len(ips) == 0 {
		return fmt.Errorf("no IP addresses found for host %q", host)
	}

	for _, ip := range ips {
		if !ip.IP.IsGlobalUnicast() {
			return fmt.Errorf("host %q resolves to non-global address %s", host, ip.IP)
		}
	}
	return nil
}

// parseHTMLPreview extracts the page title and meta description from an HTML reader.
func parseHTMLPreview(r io.Reader) (title, description string, err error) {
	doc, err := html.Parse(r)
	if err != nil {
		return "", "", err
	}

	var extractTitle, extractDesc bool
	var f func(*html.Node)
	f = func(n *html.Node) {
		if n.Type == html.ElementNode {
			switch n.Data {
			case "title":
				if !extractTitle {
					title = getTextContent(n)
					extractTitle = true
				}
			case "meta":
				if !extractDesc {
					var name, content string
					for _, attr := range n.Attr {
						if attr.Key == "name" && strings.EqualFold(attr.Val, "description") {
							name = attr.Val
						}
						if attr.Key == "content" {
							content = attr.Val
						}
					}
					if name != "" && content != "" {
						description = content
						extractDesc = true
					}
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(doc)
	return title, description, nil
}

// getTextContent returns the concatenated text content of an HTML node.
func getTextContent(n *html.Node) string {
	var sb strings.Builder
	var extract func(*html.Node)
	extract = func(n *html.Node) {
		if n.Type == html.TextNode {
			sb.WriteString(n.Data)
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			extract(c)
		}
	}
	extract(n)
	return strings.TrimSpace(sb.String())
}

