    }

    if req.URL == "" {
        resp := URLPreviewResponse{Error: "Missing 'url' field"}
        writeJSON(ctx, fasthttp.StatusBadRequest, resp)
        return
    }

    // Create client with Dial set to DialDualStack as required
    client := &fasthttp.Client{
        Dial: fasthttp.DialDualStack,
    }

    fr := fasthttp.AcquireRequest()
    defer fasthttp.ReleaseRequest(fr)
    fr.SetRequestURI(req.URL)

    fresp := fasthttp.AcquireResponse()
    defer fasthttp.ReleaseResponse(fresp)

