    err := client.DoTimeout(fr, fresp, 3*time.Second)
    if err != nil {
        resp := URLPreviewResponse{Error: fmt.Sprintf("Failed to fetch URL: %v", err)}
        writeJSON(ctx, fasthttp.StatusBadGateway, resp)
        return
    }

    htmlBytes := fresp.Body()
    title, desc := extractTitleAndDescription(htmlBytes)

    resp := URLPreviewResponse{Title: title, Description: desc}
    writeJSON(ctx, fasthttp.StatusOK, resp)
}

func writeJSON(ctx *fasthttp.RequestCtx, statusCode int, data interface{}) {
