// FetchURLPreview handles POST requests containing a JSON object with a "url" field.
// It fetches the URL, extracts the page title and meta description, and returns them as JSON.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only allow POST requests.
	if !ctx.IsPost() {
		writeJSON(ctx, 405, PreviewResponse{Error: "method not allowed"})
		return
	}

	body := ctx.PostBody()
	var req FetchRequest
	if err := json.Unmarshal(body, &req); err != nil {
		writeJSON(ctx, 400, PreviewResponse{Error: "invalid JSON: " + err.Error()})
		return
	}

	if strings.TrimSpace(req.URL) == "" {
		writeJSON(ctx, 400, PreviewResponse{Error: "url field is required"})
		return
	}

	title, desc, err := fetchAndParse(req.URL)
	if err != nil {
		writeJSON(ctx, 502, PreviewResponse{Error: err.Error()})
		return
	}

	writeJSON(ctx, 200, PreviewResponse{
		Title:       title,
		Description: desc,
	})
}

// fetchAndParse fetches the given URL using fasthttp with dual‑stack dialing,
// then parses the response body to extract the <title> and <meta name="description"> content.
func fetchAndParse(url string) (title, description string, err error) {
	// Create a fasthttp client with DualStack dialer as required.
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(url)

	// Use DoRedirects to follow up to 10 redirects (safe maximum).
	if err := client.DoRedirects(req, resp, 10); err != nil {
		return "", "", fmt.Errorf("request failed: %w", err)
	}

	body := resp.Body()
	return parseHTML(body)
}

// parseHTML extracts the page title and meta description from an HTML document.
func parseHTML(htmlContent []byte) (title, description string, err error) {
	doc, err := html.Parse(strings.NewReader(string(htmlContent)))
	if err != nil {
		return "", "", fmt.Errorf("html parse error: %w", err)
	}

	var extract func(*html.Node)
	extract = func(n *html.Node) {
		if n.Type == html.ElementNode {
			// Look for <title>
			if n.Data == "title" && title == "" {
				// Title text is the first child TextNode.
				if n.FirstChild != nil {
					title = n.FirstChild.Data
				}
			}

			// Look for <meta name="description" content="...">
			if n.Data == "meta" {
				var nameAttr, contentAttr string
				for _, attr := range n.Attr {
					if attr.Key == "name" {
						nameAttr = attr.Val
					}
					if attr.Key == "content" {
						contentAttr = attr.Val
					}
				}
				if strings.EqualFold(nameAttr, "description") && description == "" {
					description = contentAttr
				}
