// isValidURL checks whether the given URL is safe to request.
// It ensures the scheme is http/https and that the hostname resolves only to public IP addresses.
func isValidURL(u *url.URL) bool {
	if u.Scheme != "http" && u.Scheme != "https" {
		return false
	}
	if u.Host == "" {
		return false
	}
	return isPublicHost(u.Host)
}

// isPublicHost returns true if all IP addresses resolved for the hostname are public.
func isPublicHost(host string) bool {
	// Strip port if present (host may be "example.com:8080")
	hostname := host
	if _, _, err := net.SplitHostPort(host); err == nil {
		hostname = host
	}
	// net.SplitHostPort returns host without port if possible
	h, _, err := net.SplitHostPort(host)
	if err == nil {
		// It was an address with port; h is the bare host
		hostname = h
	}

	// If it's already a literal IP, check it directly
	if ip := net.ParseIP(hostname); ip != nil {
		return isPublicIP(ip)
	}

	// Resolve hostname to IP addresses
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	ips, err := net.DefaultResolver.LookupIPAddr(ctx, hostname)
	if err != nil {
		return false
	}
	for _, addr := range ips {
		if !isPublicIP(addr.IP) {
			return false
		}
	}
	return true
}

// isPublicIP returns true if the IP is not private, loopback, link-local, or unspecified.
func isPublicIP(ip net.IP) bool {
	if ip.IsLoopback() ||
		ip.IsPrivate() ||
		ip.IsLinkLocalUnicast() ||
		ip.IsLinkLocalMulticast() ||
		ip.IsUnspecified() {
		return false
	}
	return true
}

// safeDial creates a network connection after verifying the resolved IP is public.
func safeDial(addr string, timeout time.Duration) (net.Conn, error) {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, err
	}

	// Resolve and validate host
	ips, err := net.DefaultResolver.LookupIPAddr(context.Background(), host)
	if err != nil {
		return nil, err
	}
	for _, ip := range ips {
		if !isPublicIP(ip.IP) {
			return nil, fmt.Errorf("private IP address forbidden: %s", ip.IP)
		}
	}

	dialer := net.Dialer{
		Timeout:   timeout,
		KeepAlive: 30 * time.Second,
	}
	return dialer.Dial("tcp", net.JoinHostPort(host, port))
}

