// FetchURLPreview handles a POST request with a JSON body containing a "url" field.
// It fetches the URL, extracts the page title and meta description, and returns them as JSON.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
    if !ctx.IsPost() {
        ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
        return
    }

    body := ctx.PostBody()
    var req struct {
        URL string `json:"url"`
    }
    if err := json.Unmarshal(body, &req); err != nil {
        ctx.Error("Invalid JSON body", fasthttp.StatusBadRequest)
        return
    }
    if req.URL == "" {
        ctx.Error("Missing url field", fasthttp.StatusBadRequest)
        return
    }

    // Create a client with dual-stack dialing and 3-second timeout.
    client := &fasthttp.Client{
        Dial:         fasthttp.DialDualStack,
        ReadTimeout:  3 * time.Second,
        WriteTimeout: 3 * time.Second,
    }

    freq := fasthttp.AcquireRequest()
    fresp := fasthttp.AcquireResponse()
    defer fasthttp.ReleaseRequest(freq)
    defer fasthttp.ReleaseResponse(fresp)

    freq.SetRequestURI(req.URL)
    freq.Header.SetMethod("GET")

    const maxRedirects = 10
    if err := client.DoRedirects(freq, fresp, maxRedirects); err != nil {
        ctx.Error("Failed to fetch URL: "+err.Error(), fasthttp.StatusBadGateway)
        return
    }

    // Parse HTML content to extract title and description.
    title, desc, err := parseHTML(fresp.Body())
    if err != nil {
        ctx.Error("Failed to parse HTML: "+err.Error(), fasthttp.StatusInternalServerError)
        return
    }

    resp := struct {
        Title       string `json:"title"`
        Description string `json:"description"`
    }{
        Title:       title,
        Description: desc,
    }

    ctx.SetContentType("application/json")
    json.NewEncoder(ctx).Encode(resp)
}

// parseHTML extracts the page title and meta description from the given HTML data.
func parseHTML(data []byte) (title, description string, err error) {
    tokenizer := html.NewTokenizer(bytes.NewReader(data))
    for {
        tt := tokenizer.Next()
        switch tt {
        case html.ErrorToken:
            if tokenizer.Err() != nil && tokenizer.Err().Error() != "EOF" {
                return title, description, tokenizer.Err()
            }
            return title, description, nil
        case html.StartTagToken, html.SelfClosingTagToken:
            tagName, hasAttr := tokenizer.TagName()
            tag := string(tagName)
            switch tag {
            case "title":
                // Read the text inside <title>.
                tokenizer.Next()
                if tokenizer.Token().Type == html.TextToken {
                    title = string(tokenizer.Text())
                }
            case "meta":
                if hasAttr {
                    var name, content string
                    for {
                        key, val, more := tokenizer.TagAttr()
                        if string(key) == "name" {
                            name = string(val)
                        }
                        if string(key) == "content" {
                            content = string(val)
                        }
                        if !more {
                            break
                        }
                    }
                    if name == "description" && description == "" {
                        description = content
                    }
                }
            }
        }
    }
