package main

import (
	"encoding/json"
	"fmt"
	"log"
	"strings"
	"time"

	"golang.org/x/net/html"

	"github.com/valyala/fasthttp"
)

type URLPreviewRequest struct {
	URL string `json:"url"`
}

type URLPreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
	Error       string `json:"error,omitempty"`
}

func main() {
	server := &fasthttp.Server{
		Handler: requestHandler,
	}
	log.Fatal(server.ListenAndServe(":8080"))
}

func requestHandler(ctx *fasthttp.RequestCtx) {
	path := string(ctx.Path())
	if path == "/preview" {
		FetchURLPreview(ctx)
	} else {
		ctx.Error("Not Found", fasthttp.StatusNotFound)
	}
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		ctx.Error("Method Not Allowed", fasthttp.StatusMethodNotAllowed)
		return
	}

	var reqBody URLPreviewRequest
	if err := json.Unmarshal(ctx.PostBody(), &reqBody); err != nil {
		respondError(ctx, "Invalid JSON body", fasthttp.StatusBadRequest)
		return
	}

	if reqBody.URL == "" {
		respondError(ctx, "URL is required", fasthttp.StatusBadRequest)
		return
	}

	if !strings.HasPrefix(reqBody.URL, "http://") && !strings.HasPrefix(reqBody.URL, "https://") {
		respondError(ctx, "URL must start with http:// or https://", fasthttp.StatusBadRequest)
		return
	}

	title, desc, err := fetchAndParse(reqBody.URL)
	if err != nil {
		respondError(ctx, fmt.Sprintf("Failed to fetch or parse: %v", err), fasthttp.StatusInternalServerError)
		return
	}

	resp := URLPreviewResponse{
		Title:       title,
		Description: desc,
	}
	b, _ := json.Marshal(resp)
	ctx.SetContentType("application/json")
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.Write(b)
}

func respondError(ctx *fasthttp.RequestCtx, message string, statusCode int) {
	resp := URLPreviewResponse{Error: message}
	b, _ := json.Marshal(resp)
	ctx.SetContentType("application/json")
	ctx.SetStatusCode(statusCode)
	ctx.Write(b)
}

func fetchAndParse(url string) (title, description string, err error) {
	client := &fasthttp.Client{
		Dial:                fasthttp.DialDualStack,
		ReadTimeout:         10 * time.Second,
		MaxIdleConnDuration: 10 * time.Second,
	}

	req := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req)

	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(url)
	req.Header.SetMethod("GET")

	if err := client.DoRedirects(req, resp, 5); err != nil {
		return "", "", err
	}

	body := resp.Body()
	return parseHTML(body)
}

func parseHTML(body []byte) (title, description string, err error) {
	doc := strings.NewReader(string(body))
	tokenizer := html.NewTokenizer(doc)

	inTitle := false
	var titleText string

	for {
		tokenType := tokenizer.Next()
		if tokenType == html.ErrorToken {
			break
		}

		token := tokenizer.Token()

		switch tokenType {
		case html.StartTagToken, html.SelfClosingTagToken:
			if token.Data == "title" {
				inTitle = true
			} else if token.Data == "meta" {
				var name, content string
				for _, attr := range token.Attr {
					if attr.Key == "name" && attr.Val == "description" {
						name = attr.Val
					}
					if attr.Key == "content" {
						content = attr.Val
					}
				}
				if name == "description" && description == "" {
					description = content
				}
			}
		case html.TextToken:
			if inTitle {
				titleText = token.Data
				inTitle = false
			}
		case html.EndTagToken:
			if token.Data == "title" {
				inTitle = false
			}
		}
	}

	title = strings.TrimSpace(titleText)
	description = strings.TrimSpace(description)
	return title, description, nil
}

