// safeDial resolves the host, checks that none of its IP addresses are
// private or reserved, and then connects to the first IP directly to
// prevent DNS rebinding attacks.
func safeDial(addr string) (net.Conn, error) {
    host, port, err := net.SplitHostPort(addr)
    if err != nil {
        return nil, err
    }

    // Resolve the host to all IP addresses.
    ips, err := net.LookupIP(host)
    if err != nil {
        return nil, err
    }
    if len(ips) == 0 {
        return nil, fmt.Errorf("no IPs resolved for %s", host)
    }

    // Verify that none of the resolved IPs are forbidden.
    for _, ip := range ips {
        if isForbidden(ip) {
            return nil, fmt.Errorf("connection to %s is forbidden (private/reserved IP: %s)", host, ip)
        }
    }

    // Use the first IP to establish a connection, avoiding a second
    // DNS lookup that could return different (potentially private) results.
    dialer := net.Dialer{Timeout: 10 * time.Second}
    return dialer.Dial("tcp", net.JoinHostPort(ips[0].String(), port))
}

// isForbidden returns true if the IP belongs to a reserved/private range.
func isForbidden(ip net.IP) bool {
    return ip.IsLoopback() ||
        ip.IsPrivate() ||
        ip.IsLinkLocalUnicast() ||
        ip.IsLinkLocalMulticast() ||
        ip.IsUnspecified()
}

