// requestBody defines the expected JSON body.
type requestBody struct {
	URL string `json:"url"`
}

// successResponse is returned on successful extraction.
type successResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

// errorResponse is returned when something fails.
type errorResponse struct {
	Error string `json:"error"`
}

// FetchURLPreview handles POST requests to fetch a URL and extract its title
// and meta description.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only accept POST method.
	if !ctx.IsPost() {
		writeJSON(ctx, 405, errorResponse{Error: "method not allowed"})
		return
	}

	// Parse JSON body.
	var req requestBody
	body := ctx.PostBody()
	if err := json.Unmarshal(body, &req); err != nil || req.URL == "" {
		writeJSON(ctx, 400, errorResponse{Error: "invalid JSON or empty url field"})
		return
	}

	// Prepare fasthttp client with required settings.
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
		// Set per‑request timeout to 3 seconds.
		// This timeout covers the entire request lifecycle.
		// Also set client‑level timeouts as a safety net.
		ReadTimeout:  3 * time.Second,
		WriteTimeout: 3 * time.Second,
	}

	// Acquire request and response objects from pool.
	reqHTTP := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(reqHTTP)
	respHTTP := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(respHTTP)

	reqHTTP.SetRequestURI(req.URL)
	// Set per‑request timeout to exactly 3 seconds.
	reqHTTP.SetTimeout(3 * time.Second)

	// Fetch the URL, following up to 10 redirects.
	err := client.DoRedirects(reqHTTP, respHTTP, 10)
	if err != nil {
		writeJSON(ctx, 502, errorResponse{Error: "failed to fetch URL: " + err.Error()})
		return
	}

	// Check HTTP status code.
	if respHTTP.StatusCode() != fasthttp.StatusOK {
		writeJSON(ctx, 502, errorResponse{
			Error: "non‑200 status code: " + fasthttp.StatusMessage(respHTTP.StatusCode()),
		})
		return
	}

	// Parse HTML from response body.
	htmlDoc, parseErr := html.Parse(bytes.NewReader(respHTTP.Body()))
	if parseErr != nil {
		writeJSON(ctx, 500, errorResponse{Error: "HTML parsing failed: " + parseErr.Error()})
		return
	}

	title := extractTitle(htmlDoc)
	description := extractMetaDescription(htmlDoc)

	writeJSON(ctx, 200, successResponse{
		Title:       title,
		Description: description,
	})
}

// writeJSON serializes v as JSON and writes it to the context with the given status code.
func writeJSON(ctx *fasthttp.RequestCtx, statusCode int, v interface{}) {
	data, err := json.Marshal(v)
	if err != nil {
		ctx.SetStatusCode(500)
		ctx.SetBodyString(`{"error":"internal error"}`)
		return
	}
	ctx.SetStatusCode(statusCode)
	ctx.SetContentType("application/json")
	ctx.SetBody(data)
}

// extractTitle walks the HTML tree and returns the text content of the first <title> element.
func extractTitle(n *html.Node) string {
	var title string
	var crawler func(*html.Node)
	crawler = func(node *html.Node) {
		if node.Type == html.ElementNode && strings.ToLower(node.Data) == "title" {
			if node.FirstChild != nil && node.FirstChild.Type == html.TextNode {
				title = strings.TrimSpace(node.FirstChild.Data)
			}
			return
		}
		for child := node.FirstChild; child != nil; child = child.NextSibling {
			crawler(child)
		}
	}
	crawler(n)
	return title
}

// extractMetaDescription walks the HTML tree and returns the content attribute of the
// first <meta name="description"> element.
func extractMetaDescription(n *html.Node) string {
	var description string
	var crawler func(*html.Node)
	crawler = func(node *html.Node) {
		if node.Type == html.ElementNode && strings.ToLower(node.Data) == "meta" {
			var name, content string
			for _, attr := range node.Attr {
				switch strings.ToLower(attr.Key) {
				case "name":
					name = strings.ToLower(attr.Val)
				case "content":
					content = attr.Val
				}
			}
			if name == "description" {
				description = strings.TrimSpace(content)
				return
			}
		}
		for child := node.FirstChild; child != nil; child = child.NextSibling {
			crawler(child)
		}
	}
	crawler(n)
	return description
}

func main() {
	// Register the handler on the /fetch path.
