		"description": description,
	}
	js, err := json.Marshal(result)
	if err != nil {
		ctx.Error("Internal error", fasthttp.StatusInternalServerError)
		return
	}

	ctx.SetContentType("application/json")
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.Write(js)
}

