	bodyStr := string(body)
	re := regexp.MustCompile(`(?is)<title[^>]*>(.*?)</title>`)
	matches := re.FindStringSubmatch(bodyStr)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1])
	}
	return ""
}

func extractMetaDescription(body []byte) string {
	bodyStr := string(body)
	// Try common order: name then content
	re := regexp.MustCompile(`(?is)<meta[^>]+name=["']description["'][^>]+content=["'](.*?)["'][^>]*>`)
	matches := re.FindStringSubmatch(bodyStr)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1])
	}
	// Try reversed order: content then name
	re2 := regexp.MustCompile(`(?is)<meta[^>]+content=["'](.*?)["'][^>]+name=["']description["'][^>]*>`)
	matches = re2.FindStringSubmatch(bodyStr)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1])
	}
	return ""
}

