	var reqBody struct {
		URL string `json:"url"`
	}
	if err := json.Unmarshal(ctx.PostBody(), &reqBody); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"invalid JSON request body"}`))
		return
	}
	if strings.TrimSpace(reqBody.URL) == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"url field is required"}`))
		return
	}
	url := reqBody.URL

	// Prepare the HTTP client with a 3‑second timeout and dial dual‑stack.
	dialer := &net.Dialer{
		Timeout:   3 * time.Second,
		DualStack: true,
	}
	client := &fasthttp.Client{
		Dial: func(addr string) (net.Conn, error) {
			return dialer.Dial("tcp", addr)
		},
		ReadTimeout:  3 * time.Second,
		WriteTimeout: 3 * time.Second,
	}

	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(url)

