	if err := client.DoRedirects(req, resp, 10); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		errJSON, _ := json.Marshal(map[string]string{"error": "failed to fetch URL: " + err.Error()})
		ctx.SetBody(errJSON)
		return
	}

	// Extract title and meta description from the response body.
	body := resp.Body()

	title, description := "", ""
	tokenizer := html.NewTokenizer(strings.NewReader(string(body)))
	for {
		tokenType := tokenizer.Next()
		if tokenType == html.ErrorToken {
			break
		}
		if tokenType == html.StartTagToken {
			tagName, hasAttrs := tokenizer.TagName()
			tag := strings.ToLower(string(tagName))

			if tag == "title" {
