package main

import (
	"bytes"
	"encoding/json"
	"io"
	"strings"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

var httpClient = &fasthttp.Client{
	Dial: fasthttp.DialDualStack,
}

// FetchURLPreview handles POST requests with a JSON body containing a "url" field.
// It fetches the URL, extracts the page title and meta description,
// and returns them as a JSON response.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
		return
	}

	var reqData struct {
		URL string `json:"url"`
	}
	if err := json.Unmarshal(ctx.PostBody(), &reqData); err != nil || strings.TrimSpace(reqData.URL) == "" {
		ctx.Error("Invalid request: provide a valid URL", fasthttp.StatusBadRequest)
		return
	}

	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(reqData.URL)
	req.Header.SetUserAgent("Mozilla/5.0 (compatible; FetchPreview/1.0)")

	if err := httpClient.DoRedirects(req, resp, 10); err != nil {
		ctx.Error("Failed to fetch URL: "+err.Error(), fasthttp.StatusInternalServerError)
		return
	}

	if resp.StatusCode() < 200 || resp.StatusCode() > 299 {
		ctx.Error("Failed to fetch URL: unexpected status code", fasthttp.StatusInternalServerError)
		return
	}

	doc, err := html.Parse(bytes.NewReader(resp.Body()))
	if err != nil {
		ctx.Error("Failed to parse HTML: "+err.Error(), fasthttp.StatusInternalServerError)
		return
	}

	title := extractTitle(doc)
	description := extractMetaDescription(doc)

	result := map[string]string{
		"title":       title,
		"description": description,
	}
	jsonResult, err := json.Marshal(result)
	if err != nil {
		ctx.Error("Internal server error", fasthttp.StatusInternalServerError)
		return
	}

	ctx.SetContentType("application/json")
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.Write(jsonResult)
}

func extractTitle(n *html.Node) string {
	if n.Type == html.ElementNode && n.Data == "title" {
		if n.FirstChild != nil {
			return n.FirstChild.Data
		}
		return ""
	}
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		if t := extractTitle(c); t != "" {
			return t
		}
	}
	return ""
}

func extractMetaDescription(n *html.Node) string {
	if n.Type == html.ElementNode && n.Data == "meta" {
		var name, content string
		for _, a := range n.Attr {
			if a.Key == "name" && strings.ToLower(a.Val) == "description" {
				name = a.Val
			}
			if a.Key == "content" {
				content = a.Val
			}
		}
		if name != "" && content != "" {
			return content
		}
	}
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		if d := extractMetaDescription(c); d != "" {
			return d
		}
	}
	return ""
}

func main() {
	handler := func(ctx *fasthttp.RequestCtx) {
		switch string(ctx.Path()) {
		case "/fetch-preview":
			FetchURLPreview(ctx)
		default:
			ctx.Error("Not found", fasthttp.StatusNotFound)
		}
	}

	if err := fasthttp.ListenAndServe(":8080", handler); err != nil {
		panic(err)
	}
}

