    URL string `json:"url"`
}

type fetchResponse struct {
    Title       string `json:"title,omitempty"`
    Description string `json:"description,omitempty"`
    Error       string `json:"error,omitempty"`
}

// FetchURLPreview handles POST requests to fetch and preview a URL's title and meta description.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
    // Only allow POST method
    if !ctx.IsPost() {
        ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
        ctx.SetBodyString(`{"error": "only POST method is allowed"}`)
        return
    }

    // Parse JSON body
    var req fetchRequest
    if err := json.Unmarshal(ctx.PostBody(), &req); err != nil || req.URL == "" {
        ctx.SetStatusCode(fasthttp.StatusBadRequest)
        ctx.SetBodyString(`{"error": "invalid JSON: missing or empty 'url' field"}`)
        return
    }

    // Create fasthttp client with dual‑stack dial and 3‑second timeouts
    client := &fasthttp.Client{
        Dial: func(addr string) (net.Conn, error) {
            return fasthttp.DialDualStackTimeout(addr, 3*time.Second)
        },
        ReadTimeout:  3 * time.Second,
        WriteTimeout: 3 * time.Second,
    }

    // Acquire request and response objects
    fReq := fasthttp.AcquireRequest()
    fResp := fasthttp.AcquireResponse()
    defer fasthttp.ReleaseRequest(fReq)
    defer fasthttp.ReleaseResponse(fResp)

    fReq.SetRequestURI(req.URL)
    fReq.Header.SetMethod("GET")

    // Fetch the URL following redirects
    if err := client.DoRedirects(fReq, fResp, 10); err != nil {
        ctx.SetStatusCode(fasthttp.StatusInternalServerError)
        resp := fetchResponse{Error: "failed to fetch URL: " + err.Error()}
        body, _ := json.Marshal(resp)
        ctx.SetBody(body)
        return
    }

    // Parse HTML to extract title and meta description
    bodyBytes := fResp.Body()
    title, description := extractMeta(string(bodyBytes))

    // Return JSON response
    resp := fetchResponse{
        Title:       title,
        Description: description,
    }
    ctx.SetStatusCode(fasthttp.StatusOK)
    ctx.SetContentType("application/json")
    body, _ := json.Marshal(resp)
    ctx.SetBody(body)
}

// extractMeta parses the HTML string and returns the page title and meta description.
func extractMeta(htmlStr string) (title, description string) {
    z := html.NewTokenizer(strings.NewReader(htmlStr))
    inTitle := false

    for {
        tt := z.Next()
        if tt == html.ErrorToken {
            break
        }

        switch tt {
        case html.StartTagToken, html.SelfClosingTagToken:
            tn, hasAttr := z.TagName()
            tagname := string(tn)

            if tagname == "title" {
                inTitle = true
            } else if tagname == "meta" && hasAttr {
                var nameVal, contentVal string
                for {
                    key, val, more := z.TagAttr()
                    k := string(key)
                    v := string(val)
                    if k == "name" && strings.EqualFold(v, "description") {
                        nameVal = "description"
                    }
                    if k == "content" {
                        contentVal = v
                    }
                    if !more {
                        break
                    }
                }
                if nameVal == "description" && contentVal != "" {
                    description = contentVal
                }
            }

        case html.TextToken:
            if inTitle {
                title = string(z.Text())
                inTitle = false
            }
        }
    }
    return
}

func main() {
    // Start the server on port 8080
    fasthttp.ListenAndServe(":8080", FetchURLPreview)
}

